#ifndef DISPLAY_LOGIC_H
#define DISPLAY_LOGIC_H

#include "ui_types.h"
#include <stddef.h>

/* -----------------------------------------------------------------------
 * display_logic.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: Tony; Brendon (integrator) added the matching declarations (Sep 2026, 28 Oct 2026 and 29-30 Oct 2026).
 * BJT2 Sound Modulating Toy — Display Logic
 * Author: Tony (Display/UI subsystem)
 *
 * Converts ui_state_t into a display_info_t struct describing what
 * should be drawn on screen. No SPI, no HAL, no ILI9341 calls.
 * The actual draw calls read display_info_t in the real firmware.
 *
 * Also provides battery_mv_to_pct() which converts a millivolt
 * reading into a percentage (kept and tested, but the firmware no
 * longer calls it: the screens show the fuel gauge's own SoC), the hh:mm
 * formatter for the Battery screen's time to empty / to full,
 * ui_rows_changed() which tells the renderer which list rows to redraw,
 * ui_is_preparing() for the Play screen's "Preparing 45%",
 * ui_find_file() which finds a name in a list of names (kept and tested,
 * but the firmware no longer calls it: Jack's StorageReply_t.found now
 * says where the selected file is), and the Record and Play screens'
 * texts while no SD card is in the slot.
 * ----------------------------------------------------------------------- */

/* "No row" for ui_rows_changed(): no cursor or tapped row on the screen,
 * or no active effect. */
#define UI_ROW_NONE     0xFFU

/* What the Record screen's start row and the Play screen's file line say
 * while no SD card is in the slot (14 characters). */
#define UI_TEXT_INSERT_CARD "Insert SD card"

/**
 * battery_mv_to_pct
 * Converts a battery voltage in millivolts to a percentage 0-100.
 * Clamped: values at or above BATTERY_MV_MAX return 100,
 *          values at or below BATTERY_MV_MIN return 0.
 *
 * @param mv  Battery voltage in millivolts (Brendon's fuel gauge reports
 *            it as BatteryMsg_t.voltage_mV).
 * @return    Battery percentage 0-100.
 */
uint8_t battery_mv_to_pct(uint16_t mv);

/**
 * ui_effect_name
 * Human-readable name of an effect for the Effects/Play screens. Names are
 * Tom's (PD5b_Tom AudioEffectMode order): Autotune, Pitch Up, Pitch Down,
 * Robot, Echo, Reverb. EFFECT_NONE -> "None"; out of range -> "?".
 */
const char *ui_effect_name(ui_effect_t e);

/**
 * ui_format_hhmm
 * Formats a time in minutes as "hh:mm" for the Battery screen, always
 * 5 characters so the line never changes width:
 *   UI_TIME_UNKNOWN (65535, no estimate) -> "--:--"
 *   0 -> "00:00", 75 -> "01:15"
 *   6000 min (100 h) and more -> "99:59" (two hour digits cannot show it)
 *
 * @param minutes  Time in minutes, or UI_TIME_UNKNOWN.
 * @param out      Output buffer, 6 bytes or more for the whole text.
 * @param len      Size of out. Smaller buffers get a truncated, still
 *                 NUL-terminated text; NULL or 0 writes nothing.
 */
void ui_format_hhmm(uint16_t minutes, char *out, size_t len);

/**
 * ui_battery_time_label
 * Label for the Battery screen's time line: "To full" when the line
 * shows the time to full (charging), "Time left" otherwise (time to
 * empty, also on the charger while the battery drains).
 */
const char *ui_battery_time_label(bool charging);

/**
 * ui_record_start_label
 * The Record screen's start row (and its first info line while idle):
 * UI_TEXT_INSERT_CARD while Jack's newest status says the slot is empty
 * (sd_status SD_STATUS_NO_CARD), "Start Recording" otherwise, also before
 * his first status and for a NULL state.
 */
const char *ui_record_start_label(const ui_state_t *s);

/**
 * ui_play_idle_name
 * The Play screen's file line while nothing plays, first match wins:
 *   no card in the slot (SD_STATUS_NO_CARD)   UI_TEXT_INSERT_CARD
 *   file_count 0                              "No recordings"
 *   otherwise                                 selected ("" if NULL)
 *
 * @param s         UI state. NULL gives "".
 * @param selected  Name of the selected file (the File screen's choice).
 * @return          A constant text or selected, never NULL.
 */
const char *ui_play_idle_name(const ui_state_t *s, const char *selected);

/**
 * ui_fault_source_name
 * Line 1 of the fault screen: "Storage", "Battery", "USB", "Audio" or
 * "System" (ui_fault_source_t order); out of range -> "Unknown".
 */
const char *ui_fault_source_name(uint8_t source);

/**
 * ui_is_preparing
 * true while the UI is playing and Jack is making the effect file it
 * waits for (prep_pct is not UI_PREP_NONE): the Play screen then says
 * "Preparing nn%", the footer "PREPARING <name>". NULL: false.
 */
bool ui_is_preparing(const ui_state_t *s);

/**
 * ui_rows_changed
 * Which rows of a list screen (the Home tiles, the Effects rows) look
 * different after the cursor or the active effect has moved, so the
 * renderer redraws only those instead of all six. A row is drawn blue
 * while it is the cursor (hi) and marked "* " while it is the active
 * effect (active), so:
 *   prev_hi != now_hi          -> rows prev_hi and now_hi
 *   prev_active != now_active  -> rows prev_active and now_active
 * Each argument is a row index 0..7 or UI_ROW_NONE (none); an index past
 * 7 adds no row.
 *
 * @return  Bit n set = row n must be redrawn; 0 = no row changed.
 */
uint8_t ui_rows_changed(uint8_t prev_hi, uint8_t now_hi,
                        uint8_t prev_active, uint8_t now_active);

/**
 * ui_find_file
 * Where a name is in a list of names. The firmware no longer calls it:
 * since the file window (file_window.h), Jack finds the selected name
 * himself (StorageReply_t.found). The names are 8.3 names as FatFs
 * lists them (upper case, no long names), the same text Jack recorded
 * to, so the match is exact. At most DISPLAY_FILE_MAX bytes of an entry
 * are compared: an entry with no NUL is never read past its end.
 *
 * @param names  The list: count entries of DISPLAY_FILE_MAX bytes.
 * @param count  Number of entries in names.
 * @param name   The name to look for.
 * @return       Index of the first entry equal to name, or count when
 *               there is none (also for a NULL names or name and for an
 *               empty name).
 */
uint8_t ui_find_file(const char names[][DISPLAY_FILE_MAX], uint8_t count,
                     const char *name);

/**
 * ui_get_display_info
 * Builds a display_info_t from the current ui_state_t.
 * The display driver reads this struct to decide what to render.
 * No drawing happens here — purely a logic-to-display translation.
 *
 * @param s    Pointer to current UI state (read-only).
 * @param out  Pointer to display_info_t to populate.
 */
void ui_get_display_info(const ui_state_t *s, display_info_t *out);

#endif /* DISPLAY_LOGIC_H */
